  ui_story_5067_50670101_14_dialog_content = "Umm... Don't make yourselves sound so insignificant...",
  ui_story_5067_50670101_15_dialog_content = "I-I'm sure this is all just temporary!",
  ui_story_5067_50670101_16_dialog_content = "The town has been through so much lately... Everyone just needs time to heal right now...",
  ui_story_5067_50670101_17_dialog_content = "Most of the townsfolk are struggling just to meet their basic needs...",
  ui_story_5067_50670101_18_dialog_content = "If we can help them rebuild their homes and restore order to the town...",
  ui_story_5067_50670101_19_dialog_content = "I'm sure even more of them will help us rebuild your temple!",
  ui_story_5067_50670101_20_dialog_content = "Really? We're going to rebuild it?!",
