  ui_story_5067_50670101_37_dialog_content = "It's okay if you don't remember everything... If you can just give me some small ideas, I can work with that.",
  ui_story_5067_50670101_38_dialog_content = "We used to receive lots of tasty, juicy offerings all the time!",
