  ui_story_5067_50670301_3_dialog_content = "... Okay! I'll do my best to listen!",
  ui_story_5067_50670301_4_dialog_content = "Ah... I just wish you could still talk to me like you used to. It feels a bit strange now.",
  ui_story_5067_50670301_5_dialog_content = "I can hear you, but that's an order I refuse to carry out!",
