  ui_story_5067_50670301_7_dialog_content = "I see... Let's get back to the town's matters then?",
  ui_story_5067_50670301_8_dialog_content = "Yes, Queen Connolly!",
  ui_story_5067_50670301_9_dialog_content = "First, there are still a number of merman soldiers roaming around near the town. I'm putting together a scout team to help me clear them out.",
  ui_story_5067_50670301_10_dialog_content = "Getting rid of them completely is proving to be an extremely difficult task.",
