  ui_story_5067_50670301_12_dialog_content = "No, Robyn and I can handle this just fine on our own. More importantly...",
  ui_story_5067_50670301_13_dialog_content = "Plenty of townsfolk have been reporting strange hallucinations, and we could use your help with that!",
  ui_story_5067_50670301_14_dialog_content = "Wait, what...?",
  ui_story_5067_50670301_15_dialog_content = "A number of odd things have been happening in town lately, and many people claim to be seeing and hearing things too.",
  ui_story_5067_50670301_16_dialog_content = "Hallucinations... So they're seeing and hearing things that aren't really there...?",
  ui_story_5067_50670301_17_dialog_content = "Exactly, it's strange. They've begun arguing over invisible treasures and events that never occurred.",
  ui_story_5067_50670301_18_dialog_content = "Some have even resorted to violence.",
  ui_story_5067_50670301_19_dialog_content = "How could something like this be happening...?",
  ui_story_5067_50670301_20_dialog_content = "We're still in the process of rebuilding... If this keeps happening, everything will fall apart again.",
  ui_story_5067_50670301_21_dialog_content = "And then my promise to the Antons and everyone else will...",
  ui_story_5067_50670301_22_dialog_content = "If only the Aqua Lord was here to guide me...",
  ui_story_5067_50670301_23_dialog_content = "No, this is my responsibility to bear! I need to come up with an answer all by myself!",
  ui_story_5067_50670301_24_dialog_content = "Looks like you're out of ideas too, huh?",
  ui_story_5067_50670301_25_dialog_content = "The White Dolphin said that some of the townsfolk are really knowledgeable too...",
  ui_story_5067_50670301_26_dialog_content = "Maybe one of them can help me solve this problem... Do you know of anyone like that?",
  ui_story_5067_50670301_27_dialog_content = "Someone knowledgeable... I think I know someone who fits the bill...",
  ui_story_5067_50670301_28_dialog_content = "A sage who once followed the legendary hero Istvan. She is known as—The Lady in the Teapot!",
  ui_story_5067_50670301_29_dialog_content = "Rumor has it that she is immensely wealthy and lives in seclusion in a secret mansion where a boat is docked in the sea.",
  ui_story_5067_50670301_30_dialog_content = "With her wisdom, she might be able to point you in the right direction.",
  ui_story_5067_50670301_31_dialog_content = "Thank you... Thank you so much, Dayna. I'll think of a way to find this sage...",
  ui_story_5067_50670301_32_dialog_content = "The Lady in the Teapot... Right?",
  ui_story_5067_50670301_33_dialog_content = "Let's get going!",
  ui_story_5067_50670301_34_dialog_content = "You could do with a royal advisor, Connolly.",
  ui_story_5067_50670301_35_dialog_content = "Solving problems would be a lot easier with one.",
  ui_story_5067_50670301_36_dialog_content = "I... I know. I just have to pluck up the courage... to ask her to be my advisor!",
  ui_story_5067_50670501_1_dialog_content = "Is... Is this the place...?",
  ui_story_5067_50670501_2_dialog_content = "Um... Pardon me, but is the Lady in the Teapot available right now...?",
  ui_story_5067_50670501_3_dialog_content = "Well well, if it isn't Connolly... The new queen of the town.",
  ui_story_5067_50670501_4_dialog_content = "Let me guess, you've run into some kind of problem and require my advice?",
  ui_story_5067_50670501_5_dialog_content = "Huh...? H-How did you know...?",
  ui_story_5067_50670501_6_dialog_content = "Nothing that happens at the bottom of the sea escapes my knowledge. Let's just see...",
  ui_story_5067_50670501_7_dialog_content = "If your request is even worthy of consideration!",
  ui_story_5067_50670501_8_dialog_content = "Well... The people in town have been seeing and hearing strange things lately...",
  ui_story_5067_50670501_9_dialog_content = "I wanted to know if you could tell me the cause of these hallucinations!",
  ui_story_5067_50670501_10_dialog_content = "As the queen, I have to find a way to get rid of them...",
  ui_story_5067_50670501_11_dialog_content = "Otherwise it'll ruin our reconstruction efforts, and plunge the whole town into chaos again!",
  ui_story_5067_50670501_12_dialog_content = "The story behind this matter is a long and intricate one, and is also inextricably connected to you.",
  ui_story_5067_50670501_13_dialog_content = "Surely you're aware of the Aqua Lord's history, yes?",
  ui_story_5067_50670501_14_dialog_content = "Uh... W-Well, the Aqua Lord was dormant for a very long time, and really didn't mention any of its past to me.",
  ui_story_5067_50670501_15_dialog_content = "Heheh, so you're not aware at all. Did you know that the Aqua Lord was once known as the god of fear and pain?",
  ui_story_5067_50670501_16_dialog_content = "Fear... and pain?!",
  ui_story_5067_50670501_17_dialog_content = "Indeed. The Aqua Lord's terrible visage forced others to obey out of fear, and its absolute power brought unbearable pain to all who trespassed on its domain.",
  ui_story_5067_50670501_18_dialog_content = "The Aqua Lord was a truly dangerous deity in its time.",
  ui_story_5067_50670501_19_dialog_content = "...",
  ui_story_5067_50670501_20_dialog_content = "But... But I never thought it was all that scary...",
  ui_story_5067_50670501_21_dialog_content = "Oho? You may be right. After all, a god doesn't choose its purpose for itself.",
  ui_story_5067_50670501_22_dialog_content = "Its death and rebirth, however, inevitably produce many fragments of power.",
  ui_story_5067_50670501_23_dialog_content = "The current situation is no different.",
  ui_story_5067_50670501_24_dialog_content = "It's likely that the source of the hallucinations in both the townspeople and the merman soldiers is the very same power.",
  ui_story_5067_50670501_25_dialog_content = "Though they're only fragments of the Aqua Lord's original power, they've already impacted the town in a very significant way.",
  ui_story_5067_50670501_26_dialog_content = "If this is the case, do you truly intend to resolve this dilemma personally?",
  ui_story_5067_50670501_27_dialog_content = "Of course. It's my duty to resolve it as the queen.",
  ui_story_5067_50670501_28_dialog_content = "I just don't know how these fragments of power will affect the Antons...",
  ui_story_5067_50670501_29_dialog_content = "Oh... You're worried about those little things?",
  ui_story_5067_50670501_30_dialog_content = "It's perfectly natural to want the Aqua Lord's power fragments for yourself...",
  ui_story_5067_50670501_31_dialog_content = "Reconstructing a temple of faith should be simple enough with that kind of power.",
  ui_story_5067_50670501_32_dialog_content = "It'd be nice to give them a new home as soon as possible... but...",
  ui_story_5067_50670501_33_dialog_content = "You worry that rebuilding their temple will restore their original power... don't you?",
  ui_story_5067_50670501_34_dialog_content = "... You're afraid that they'll become symbols of fear and pain once again...",
  ui_story_5067_50670501_35_dialog_content = "Well... It's just...",
  ui_story_5067_50670501_36_dialog_content = "You look so cute when you're worried...",
  ui_story_5067_50670501_37_dialog_content = "But fret not, my dear. You have very little to fear.",
  ui_story_5067_50670501_38_dialog_content = "As those little ones slowly regain their previous power, whether they will ascend to a throne of terror...",
  ui_story_5067_50670501_39_dialog_content = "Or become something entirely different...",
  ui_story_5067_50670501_40_dialog_content = "It all depends on your thoughts, Connolly. After all, the only one who can control them is you.",
  ui_story_5067_50670501_41_dialog_content = "My... thoughts...?",
  ui_story_5067_50670501_42_dialog_content = "I understand. I'll... I'll do what I think is right.",
  ui_story_5067_50670501_43_dialog_content = "They're my important companions, as well as the protectors of this town. I... I shouldn't doubt them like this.",
  ui_story_5067_50670501_44_dialog_content = "Very good. Now go and do what you feel is right, and do it with conviction. I'm more than willing to continue offering my advice as well.",
  ui_story_5067_50670501_45_dialog_content = "As for my payment... Heheh, don't worry my dear, I'll be sure to give you a good deal.",
  ui_story_5067_50670601_1_dialog_content = "Phew... We haven't gotten any reports of hallucinations for a long time now...",
  ui_story_5067_50670601_2_dialog_content = "Now that the town is at peace again, I wonder how the temple's reconstruction is going...?",
  ui_story_5067_50670601_3_dialog_content = "Look, it's Queen Connolly!",
  ui_story_5067_50670601_4_dialog_content = "Our town is so much safer because of your protection! Long live the queen!",
  ui_story_5067_50670601_5_dialog_content = "Long live Queen Connolly, the one who saved us from our painful memories!",
  ui_story_5067_50670601_6_dialog_content = "Without her gracious intervention, who knows how long we would have been plagued by those hallucinations...",
  ui_story_5067_50670601_7_dialog_content = "Wait... Wait!",
  ui_story_5067_50670601_8_dialog_content = "Not you people again! What do you want with our queen this time?!",
  ui_story_5067_50670601_9_dialog_content = "Please don't misunderstand! W-We've come to offer Queen Connolly our gratitude as well!",
  ui_story_5067_50670601_10_dialog_content = "Despite our constant attempts to capture her in the past, she still saw fit to free us from those nightmarish hallucinations....",
  ui_story_5067_50670601_11_dialog_content = "Your Majesty! If you wouldn't mind, we'd also like to offer our help!",
  ui_story_5067_50670601_12_dialog_content = "If you really want to help...",
  ui_story_5067_50670601_13_dialog_content = "Very well then! We could really use a few more hands to finish the temple's reconstruction, so head over there and see what they need!",
  ui_story_5067_50670601_14_dialog_content = "As you wish, Queen Connolly!",
  ui_story_5067_50670601_15_dialog_content = "Transition",
  ui_story_5067_50670601_16_dialog_content = "Some time later—",
  ui_story_5067_50670601_17_dialog_content = "I hereby declare that the construction of Queen Connolly's temple... is officially complete!",
  ui_story_5067_50670601_18_dialog_content = "Long live the queen! Long live the queen!",
  ui_story_5067_50670601_19_dialog_content = "Now that the Aqua Queen has a new temple, our town can enjoy long-lasting peace once again!",
  ui_story_5067_50670601_20_dialog_content = "Thanks to the queen, we were able to rebuild our home.",
  ui_story_5067_50670601_21_dialog_content = "Look! Is that her...?",
  ui_story_5067_50670601_22_dialog_content = "Connolly! Connolly! Connolly!",
  ui_story_5067_50670601_23_dialog_content = "Ahhhhh... Th-That's enough, everyone! You're embarrassing me...",
  ui_story_5067_50670601_24_dialog_content = "Phew, I finally got away. Even though it doesn't bother me that much, everyone's still a little too excited...",
  ui_story_5067_50670601_25_dialog_content = "But more importantly...",
  ui_story_5067_50670601_26_dialog_content = "Our home! Our brand-new temple home! Hmm-hmm-hmm!",
  ui_story_5067_50670601_27_dialog_content = "In all this time, the Antons haven't calmed down even a little bit...",
  ui_story_5067_50670601_28_dialog_content = "They must be so happy... How do you like your new home, guys?",
  ui_story_5067_50670601_29_dialog_content = "It's perfect, Connolly! We love you so much!",
  ui_story_5067_50670601_30_dialog_content = "It's even more magnificent than we imagined. Thank you.",
  ui_story_5067_50670601_31_dialog_content = "Our memories are slowly coming back.",
  ui_story_5067_50670601_32_dialog_content = "Huh? You mean... You're starting to remember your past?",
  ui_story_5067_50670601_33_dialog_content = "Yes, and lots of it!",
  ui_story_5067_50670601_34_dialog_content = "Our divinity is returning to us as we speak.",
  ui_story_5067_50670601_35_dialog_content = "The weight of our power and purpose.",
  ui_story_5067_50670601_36_dialog_content = "What?! I mean... Is that so? I'm so happy for the three of you...",
  ui_story_5067_50670601_37_dialog_content = "(But according to the Lady in the Teapot...)",
  ui_story_5067_50670601_38_dialog_content = "(Does this mean a god of fear and pain is about to be reborn?)",
  ui_story_5067_50670601_39_dialog_content = "If that happens...",
  ui_story_5067_50670601_40_dialog_content = "No, I believe a new god will come to reside in this beautiful, new temple.",
  ui_story_5067_50670601_41_dialog_content = "Huh? That voice...",
  ui_story_5067_50670601_42_dialog_content = "And this god will have a new name, one that's full of kindness and joy.",
  ui_story_5067_50670601_43_dialog_content = "Perhaps it'll be... A god of music and friendship?",
  ui_story_5067_50670601_44_dialog_content = "It's you... the White Dolphin...",
  ui_story_5067_50670601_45_dialog_content = "Wait for me! I'm coming to find you!",
  ui_story_5067_50670801_1_dialog_content = "Haa... Haa... White Dolphin... I thought...",
  ui_story_5067_50670801_2_dialog_content = "I thought I'd never hear from you again.",
  ui_story_5067_50670801_3_dialog_content = "Don't worry. I've always been right at your side.",
  ui_story_5067_50670801_4_dialog_content = "But after seeing how well you've done all this time, I thought this would be best.",
  ui_story_5067_50670801_5_dialog_content = "You think I've... Done well?",
  ui_story_5067_50670801_6_dialog_content = "Of course. And now, you and the Antons have mastered the power of a new god.",
  ui_story_5067_50670801_7_dialog_content = "Huh...?!",
  ui_story_5067_50670801_8_dialog_content = "Just look... You can see every fish in every street of the town now, can't you?",
