  ui_story_5067_50670801_10_dialog_content = "Th-This is incredible! It feels just like a dream!",
  ui_story_5067_50670801_11_dialog_content = "Could I actually be dreaming right now?",
  ui_story_5067_50670801_12_dialog_content = "Oh? Have you finally noticed?",
  ui_story_5067_50670801_13_dialog_content = "Huh...? I knew it...",
  ui_story_5067_50670801_14_dialog_content = "But this is no ordinary dream, Connolly.",
  ui_story_5067_50670801_15_dialog_content = "The fear and pain that the Aqua Lord once embodied is actually the source of your latent power.",
  ui_story_5067_50670801_16_dialog_content = "In the past, you developed the power to connect with the void in order to avoid pain and cope with your fears.",
  ui_story_5067_50670801_17_dialog_content = "My past... I see...",
  ui_story_5067_50670801_18_dialog_content = "Back then, there was a lot of fear and pain that I wanted to escape from...",
  ui_story_5067_50670801_19_dialog_content = "But after all of your trials and tribulations, you've finally come to realize something, right?",
  ui_story_5067_50670801_20_dialog_content = "The importance of having companions and a place to call home, as well as the trust and kindness of other people.",
  ui_story_5067_50670801_21_dialog_content = "Becoming a new god means you no longer have to hide from fear or pain behind a mask.",
  ui_story_5067_50670801_22_dialog_content = "Music and friendship: these are what led you to your new status.",
  ui_story_5067_50670801_23_dialog_content = "I... You're right. My friends, and the townspeople... They're the ones who made me this way.",
  ui_story_5067_50670801_24_dialog_content = "And of course there's you, White Dolphin... Without you, I...",
  ui_story_5067_50670801_25_dialog_content = "There's no need to say that. As I've told you many times now, your growth is all thanks to your own hard work.",
  ui_story_5067_50670801_26_dialog_content = "You're no longer the panicking little girl you used to be, so please be more confident in yourself.",
  ui_story_5067_50670801_27_dialog_content = "Your power isn't for hiding anymore, but for bringing music, courage, and love to the hearts of others.",
  ui_story_5067_50670801_28_dialog_content = "Can... Can I really possess something so beautiful?",
  ui_story_5067_50670801_29_dialog_content = "You've always had this power, Connolly. In fact, these are your most defining traits.",
  ui_story_5067_50670801_30_dialog_content = "Now then, it's time for you to wake up from this dream.",
  ui_story_5067_50670801_31_dialog_content = "But...",
  ui_story_5067_50670801_32_dialog_content = "Are you ready?",
  ui_story_5067_50670801_33_dialog_content = "I...",
  ui_story_5067_50670801_34_dialog_content = "I am.",
  ui_story_5067_50670801_35_dialog_content = "In the real world, I might hesitate or shy away from things at times...",
  ui_story_5067_50670801_36_dialog_content = "But as my friends... You'll always be there to remind me of who I am, right?",
  ui_story_5067_50670801_37_dialog_content = "Of course!",
  ui_story_5067_50670801_38_dialog_content = "I'll come see you at the Holiday Cafe someday, so make sure to prepare your best cup of coffee for me when that day comes.",
  ui_story_5067_50670801_39_dialog_content = "It's a promise!"
}
return config
